import React, { useEffect, useRef } from 'react';
import { useIframeViewportVisibility } from '../../../hooks/useIframeViewportVisibility';

interface UrbanTractionComparisonsProps {
  className?: string;
  title?: string;
  contentCss?: string;
  disableAutoHeight?: boolean;
  disableScroll?: boolean;
}

// React copy of public/urban-traction-row-4up.html; the original HTML remains the fallback implementation.
const sourceDocument = String.raw`<!DOCTYPE html>
<html lang="en" data-theme="light">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Urban Traction — transformation</title>
<style>
:root{
  --bg-primary:#fff; --text-primary:#1A1A1A; --text-secondary:#8A8A8A;
  --border-subtle:#E4E4E2; --slot:#B5342B; --plate:#fff;
  --edge:clamp(20px,3.2vw,58px);
  --gap:clamp(14px,1.7vw,30px);
}
[data-theme="dark"]{
  --bg-primary:#0C0C0C; --text-primary:#EDEBE6; --text-secondary:#87837B;
  --border-subtle:#242423; --slot:#E0776C; --plate:#0C0C0C;
}
*{box-sizing:border-box}
body{margin:0;background:var(--bg-primary);color:var(--text-primary);
  font-family:"PWC-Medium",Arial,Helvetica,sans-serif;
  font-size:15px;line-height:1.6;-webkit-font-smoothing:antialiased;
  overflow-x:hidden;transition:background .4s,color .4s}
img{display:block;width:100%;height:100%;max-width:none;object-fit:cover}
h1,h2,h3,p,figure{margin:0;padding:0}
button{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:pointer}

/* full-width transformation row with four equal panels */
.band{width:100%;max-width:none;margin:0 auto;padding:clamp(40px,7vh,92px) var(--edge)}
.band__head{text-align:center;margin-bottom:clamp(24px,3.2vw,46px)}
.band__head h2{font-size:12px;font-weight:500;letter-spacing:.17em;text-transform:uppercase}
.band__head p{font-size:10.5px;letter-spacing:.13em;text-transform:uppercase;
  color:var(--text-secondary);margin-top:6px}

.row{display:grid;grid-template-columns:repeat(4,1fr);gap:var(--gap);
  row-gap:clamp(26px,3.4vw,46px);align-items:start}

.panel__label{display:flex;justify-content:space-between;align-items:baseline;gap:10px;
  padding-bottom:8px;margin-bottom:10px;border-bottom:1px solid var(--border-subtle)}
.panel__label h3{font-size:10.5px;font-weight:500;letter-spacing:.14em;text-transform:uppercase}
.panel__label span{font-size:10px;letter-spacing:.1em;color:var(--text-secondary)}

.stage{position:relative;background:var(--plate);overflow:hidden;user-select:none;
  aspect-ratio:1400/725}
.stage figure{position:absolute;inset:0;opacity:0;transition:opacity .55s ease}
.stage figure.on{opacity:1}
.stage figure.on img{animation:drift 5s ease-out forwards}
@keyframes drift{from{transform:scale(1)}to{transform:scale(1.013)}}

.badge{position:absolute;left:0;top:0;z-index:3;
  font-size:9px;font-weight:500;letter-spacing:.17em;text-transform:uppercase;
  padding:6px 11px;background:rgba(255,255,255,.92);color:#1A1A1A;
  transition:background .4s ease,color .4s ease}
.badge.is-proposed{background:rgba(26,26,26,.9);color:#fff}

.half{position:absolute;top:0;bottom:0;width:50%;z-index:2}
.half.prev{left:0} .half.next{right:0}
@media (hover:hover){ .half{cursor:none} }

.cap{margin-top:11px;font-size:11.5px;line-height:1.58;color:var(--text-secondary);
  transition:opacity .3s ease;min-height:6.4em}
.cap .key{font-weight:500;color:var(--text-primary)}

.controls{display:flex;flex-direction:column;align-items:center;margin-top:clamp(24px,3vw,44px)}
.counter{font-size:12.5px;letter-spacing:.06em}
.counter .now{color:var(--text-secondary)}
.track{display:flex;gap:5px;margin-top:13px}
.track button{width:48px;height:2px;background:var(--border-subtle);transition:background .3s}
.track button[aria-current="true"]{background:var(--text-primary)}
.hint{margin-top:15px;font-size:9.5px;letter-spacing:.15em;
  text-transform:uppercase;color:var(--text-secondary)}

.cursor{position:fixed;z-index:60;pointer-events:none;opacity:0;
  transform:translate(-50%,-50%) scale(.7);transition:opacity .22s,transform .22s}
.cursor svg{width:36px;height:36px;stroke:var(--text-primary);fill:none;stroke-width:1.2}
.cursor.on{opacity:1;transform:translate(-50%,-50%) scale(1)}
.cursor.flip svg{transform:scaleX(-1)}
@media (hover:none){.cursor{display:none}}

.credit{max-width:1350px;margin:0 auto;padding:0 var(--edge) 50px;
  font-size:10px;color:var(--text-secondary);text-align:center}

@media (prefers-reduced-motion:reduce){
  .stage figure{transition:none} .stage figure.on img{animation:none}
}

/* a 2x2 holds at every desktop size; single column once a pair no longer fits */
@media (max-width:680px){
  .row{grid-template-columns:1fr}
  .cap{min-height:0}
}


.bar button{border:1px solid var(--border-subtle);padding:7px 11px;font-size:9.5px;
  letter-spacing:.14em;text-transform:uppercase;color:var(--text-secondary);background:var(--bg-primary)}

/* Portfolio type system: headings use PWC-Bold; supporting copy uses PWC-Medium. */
h1,h2,h3,h4,h5,h6,.title,.ttl,.h1,.h2,.seq-title,.band__head h2,.panel__label h3,.study__head h1,.seq__head h2,.mlist h2,.feature .side h3 { font-family:"PWC-Bold",Arial,Helvetica,sans-serif; font-weight:700; }
body { font-family:"PWC-Medium",Arial,Helvetica,sans-serif; }
</style>
</head>
<body>

<div class="cursor" id="cursor" aria-hidden="true">
  <svg viewBox="0 0 40 40"><path d="M13 8 L28 20 L13 32 Z"/></svg>
</div>

<section class="band" aria-label="Urban Traction transformation">
  <div class="band__head">
    <h2>Transformation</h2>
    <p>Urban Traction &middot; Grandview Woodland, Vancouver</p>
  </div>
  <div class="row" id="row"></div>
  <div class="controls">
    <p class="counter"><span class="now" id="now">01</span> / <span id="tot">02</span></p>
    <div class="track" id="track"></div>
  </div>
</section>




<script>
/* All three panels step together: every street shows EXISTING, then every street
   flips to PROPOSED. Set SYNC to false to let each panel run on its own. */
const SYNC = true;

const PANELS = [
 { id:'arterial', title:'Arterial street', place:'Four lanes',
   steps:[
    {img:'data:image/jpeg;base64,', state:'existing', key:'EXISTING',
     text:'Four lanes of carriageway with parking on both edges. Overhead wiring, no street trees, and a footway too narrow to hold anything but movement.'},
    {img:'data:image/jpeg;base64,', state:'proposed', key:'PROPOSED',
     text:'The carriageway is reduced and the released width given to a continuous bike lane, a planted verge and a widened footway, under a double row of trees.'},
   ]},
 { id:'corridor', title:'Industrial corridor', place:'Through route',
   steps:[
    {img:'data:image/jpeg;base64,', state:'existing', key:'EXISTING',
     text:'A through route edged with parking and overhead power lines. Frontages set back behind asphalt, with nothing between the traffic and the buildings.'},
    {img:'data:image/jpeg;base64,', state:'proposed', key:'PROPOSED',
     text:'The carriageway narrows to two lanes. Planted verges, protected cycle lanes and a paved kerbside edge take the width that parking gave up.'},
   ]},
 { id:'lane', title:'Service lane', place:'Mid-block',
   steps:[
    {img:'data:image/jpeg;base64,', state:'existing', key:'EXISTING',
     text:'A service lane given over entirely to parking. Blank building edges on both sides, and no reason to stop.'},
    {img:'data:image/jpeg;base64,', state:'proposed', key:'PROPOSED',
     text:'Surface parking is removed and the lane becomes shared frontage — awnings, seating and spill-out tables on one side, a cycle route and planting on the other.'},
   ]},
 { id:'alley', title:'Rear alley', place:'Service access',
   steps:[
    {img:'data:image/jpeg;base64,', state:'existing', key:'EXISTING',
     text:'A narrow alley running between blank building walls. Overhead wiring, roller shutters and a strip of asphalt doing nothing but service access.'},
    {img:'data:image/jpeg;base64,', state:'proposed', key:'PROPOSED',
     text:'The alley is resurfaced as a shared way — paved walks and planted verges on both sides, with deliveries kept to a single slow lane through the middle.'},
   ]},
];

const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;
const cur = document.getElementById('cursor');
const row = document.getElementById('row');
const track = document.getElementById('track');
const nowEl = document.getElementById('now');
const pad = n => String(n).padStart(2,'0');
const COUNT = Math.max(...PANELS.map(p => p.steps.length));
document.getElementById('tot').textContent = pad(COUNT);

PANELS.forEach(p => {
  const el = document.createElement('div');
  el.className = 'panel';
  el.innerHTML = ${'`'}
    <div class="panel__label"><h3>${'${'}p.title}</h3><span>${'${'}p.place}</span></div>
    <div class="stage" role="group" aria-label="${'${'}p.title}">
      <span class="badge" aria-hidden="true"></span>
      <button class="half prev" aria-label="Previous"></button>
      <button class="half next" aria-label="Next"></button>
    </div>
    <p class="cap" aria-live="polite"></p>${'`'};
  row.appendChild(el);

  p.stage = el.querySelector('.stage');
  p.cap   = el.querySelector('.cap');
  p.badge = el.querySelector('.badge');
  p.at    = -1;

  p.steps.forEach((s,i) => {
    const f = document.createElement('figure');
    f.innerHTML = ${'`'}<img src="${'${'}s.img}" alt="${'${'}p.title}, ${'${'}s.key.toLowerCase()} condition" ${'${'}i?'loading="lazy"':''}>${'`'};
    p.stage.appendChild(f); s.el = f;
  });

  p.stage.tabIndex = 0;
  p.stage.querySelector('.next').onclick = () => step(p, +1, true);
  p.stage.querySelector('.prev').onclick = () => step(p, -1, true);
  p.stage.addEventListener('keydown', e => {
    if(e.key==='ArrowRight'){ e.preventDefault(); step(p, +1, true); }
    if(e.key==='ArrowLeft'){  e.preventDefault(); step(p, -1, true); }
  });
  p.stage.addEventListener('pointerenter', () => { paused = true; clearInterval(timer); });
  p.stage.addEventListener('pointerleave', () => { paused = false; cur.classList.remove('on'); restart(); });
  if(matchMedia('(hover:hover)').matches){
    p.stage.addEventListener('pointermove', e => {
      cur.classList.add('on');
      cur.style.left = e.clientX+'px'; cur.style.top = e.clientY+'px';
      const r = p.stage.getBoundingClientRect();
      cur.classList.toggle('flip', e.clientX < r.left + r.width/2);
    });
  }
});

for(let i=0;i<COUNT;i++){
  const b=document.createElement('button');
  b.setAttribute('aria-label',${'`'}Step ${'${'}i+1}${'`'});
  b.onclick=()=>goAll(i,true);
  track.appendChild(b);
}

function render(p, i){
  i = (i + p.steps.length) % p.steps.length;
  if(i === p.at) return;
  p.steps.forEach((s,k) => {
    s.el.classList.toggle('on', k===i);
    if(k===i && !REDUCED){
      const img = s.el.querySelector('img');
      img.style.animation='none'; void img.offsetWidth; img.style.animation='';
    }
  });
  const s = p.steps[i];
  p.badge.textContent = s.key;
  p.badge.classList.toggle('is-proposed', s.state==='proposed');
  p.cap.style.opacity = 0;
  setTimeout(() => {
    p.cap.innerHTML = ${'`'}<span class="key">${'${'}s.key}</span> &mdash; ${'${'}s.text}${'`'};
    p.cap.style.opacity = 1;
  }, p.at===-1 ? 0 : 160);
  p.at = i;
}

function goAll(i, manual){
  PANELS.forEach(p => render(p, i));
  [...track.children].forEach((b,k) => b.setAttribute('aria-current', String(k===i)));
  nowEl.textContent = pad(i+1);
  if(manual) restart();
}

function step(p, dir, manual){
  if(SYNC){ goAll((PANELS[0].at + dir + COUNT) % COUNT, manual); return; }
  render(p, p.at + dir);
  if(manual) restart();
}

let timer = null, paused = false, visible = false, parentVisible = true;
const DWELL = 4200;
function restart(){
  clearInterval(timer);
  if(visible && parentVisible && !paused && !REDUCED) timer = setInterval(() => goAll((PANELS[0].at + 1) % COUNT), DWELL);
}

window.addEventListener('message',e=>{
  if(e.source!==parent || e.data?.type!=='portfolio:iframe-viewport-visibility') return;
  parentVisible=Boolean(e.data.isVisible);
  if(visible && parentVisible) restart();
  else clearInterval(timer);
});
new IntersectionObserver((es) => {
  visible = es[0].isIntersecting;
  if(visible && parentVisible) restart();
  else clearInterval(timer);
}, {threshold:.2}).observe(row);
goAll(0);


</script>
</body>
</html>
`;


export const UrbanTractionComparisons: React.FC<UrbanTractionComparisonsProps> = ({ className = 'block h-full w-full border-0', title = 'Urban Traction existing and proposed comparisons', contentCss, disableAutoHeight, disableScroll }) => {
  const frameRef = useRef<HTMLIFrameElement>(null);
  useIframeViewportVisibility(frameRef);

  useEffect(() => {
    const frame = frameRef.current;
    if (!frame) return;
    const applyContentCss = () => {
      if (!contentCss) return;
      const doc = frame.contentDocument;
      if (!doc?.head) return;
      let style = doc.head.querySelector<HTMLStyleElement>('style[data-parent-layout-overrides]');
      if (!style) {
        style = doc.createElement('style');
        style.dataset.parentLayoutOverrides = '';
        doc.head.appendChild(style);
      }
      style.textContent = contentCss;
    };
    const fitFrame = () => {
      if (disableAutoHeight) return;
      const doc = frame.contentDocument;
      if (!doc?.body) return;
      const height = Math.max(doc.body.scrollHeight, doc.body.offsetHeight);
      if (height > 0) frame.style.height = `${height}px`;
    };
    const observeContent = () => {
      applyContentCss();
      fitFrame();
    };
    frame.addEventListener('load', observeContent);
    window.addEventListener('resize', fitFrame);
    return () => {
      frame.removeEventListener('load', observeContent);
      window.removeEventListener('resize', fitFrame);
    };
  }, [contentCss, disableAutoHeight]);

  return <iframe ref={frameRef} srcDoc={sourceDocument} title={title} loading="lazy" scrolling={disableScroll ? 'no' : undefined} className={className} />;
};
